    reasoning = assessment.get("reasoning") or ""
    for phrase in ("deliberately", "intended to", "tried to hide", "wanted to",
                   "in order to avoid", "knowingly"):
        if phrase in reasoning.lower():
            p.warn(where, f"assessment.reasoning contains {phrase!r} — reads as a motive "
                          "claim; restate as conduct")
    return status


