                         publishable: bool) -> None:
    if not isinstance(ror, dict):
        p.error(where, "right_of_reply must be an object")
        return
    if not isinstance(ror.get("requested"), bool):
        p.error(where, "right_of_reply.requested must be true or false")
    if ror.get("requested"):
