        check_source(p, where, "commitment", data.get("commitment"))

    observations = data.get("observations")
    if not isinstance(observations, list):
        if "observations" in data:
            p.error(where, "observations must be an array (may be empty)")
    else:
        for i, observation in enumerate(observations):
            check_source(p, where, f"observations[{i}]", observation)

    status = check_assessment(p, where, data.get("assessment")) if "assessment" in data else None

    # An empty observation list is legitimate only for statuses that assert nothing.
    if isinstance(observations, list) and not observations:
        if status in ADVERSE_STATUSES or status == "met":
            p.error(where, f"status {status!r} asserts a finding but there are no observations")
        else:
            p.warn(where, "no observations recorded — acceptable for an open question, and "
                          "'unclear' is itself a finding worth publishing")

    if "right_of_reply" in data:
        check_right_of_reply(p, where, data.get("right_of_reply"), status, publishable)
    if "corrections" in data:
        check_corrections(p, where, data.get("corrections"))

    reviewed = data.get("last_reviewed")
    check_date(p, where, "last_reviewed", reviewed)
    reviewed_date = parse_date(reviewed)
    if reviewed_date is not None:
        age = (dt.date.today() - reviewed_date).days
        if age > REVIEW_MAX_AGE_DAYS:
            p.error(where, f"last_reviewed is {age} days old (limit {REVIEW_MAX_AGE_DAYS}) — "
                           "stale entries get cited; review or retire it")
        elif age > REVIEW_MAX_AGE_DAYS - 30:
            p.warn(where, f"last_reviewed is {age} days old — review due soon")


def main() -> int:
    parser = argparse.ArgumentParser(description="Validate ledger entries.")
    parser.add_argument("--strict", action="store_true",
                       help="treat placeholder entries as errors")
    parser.add_argument("--publishable", action="store_true",
                       help="apply pre-publication gates (right of reply, no placeholders)")
    args = parser.parse_args()

    if not ENTRY_DIR.is_dir():
        print(f"error: no entry directory at {ENTRY_DIR}", file=sys.stderr)
        return 1

    paths = sorted(ENTRY_DIR.glob("*.json"))
    if not paths:
        print(f"error: no entries found in {ENTRY_DIR}", file=sys.stderr)
        return 1

    p = Problems()
    seen_ids: dict[str, str] = {}
    for path in paths:
        validate_entry(path, p, seen_ids, args.strict, args.publishable)

    for warning in p.warnings:
        print(f"WARN  {warning}")
    for error in p.errors:
        print(f"ERROR {error}")

    print(f"\n{len(paths)} entr{'y' if len(paths) == 1 else 'ies'} checked; "
          f"{len(p.errors)} error(s), {len(p.warnings)} warning(s).")
    return 1 if p.errors else 0


if __name__ == "__main__":
    sys.exit(main())

