        check_url(p, where, f"{label}.source_url", source.get("source_url"))
    if "archive_url" in source:
        check_url(p, where, f"{label}.archive_url", source.get("archive_url"))
        # Methodology section 3.3: the snapshot is the point. A snapshot that is just the
        # live URL again is not a snapshot.
        if source.get("archive_url") == source.get("source_url"):
            p.error(where, f"{label}.archive_url is identical to source_url — no snapshot taken")
