    if ror.get("response_received_on") is not None:
        check_date(p, where, "right_of_reply.response_received_on",
                   ror.get("response_received_on"))
        if not is_nonempty_str(ror.get("response_text")):
            p.error(where, "a response date is recorded but response_text is empty — "
                           "the methodology requires publishing the response verbatim")
    if publishable and status in ADVERSE_STATUSES and not ror.get("requested"):
        p.error(where, f"status {status!r} cannot be published until right of reply has been "
                       "requested (METHODOLOGY section 6)")


def check_corrections(p: Problems, where: str, corrections) -> None:
    if not isinstance(corrections, list):
