* { box-sizing:border-box; }
body { margin:0 auto; padding:2.5rem 1.25rem 5rem; max-width:46rem; background:var(--bg);
  color:var(--fg); font:16px/1.65 Georgia, "Iowan Old Style", serif; }
header.site { border-bottom:2px solid var(--fg); padding-bottom:.75rem; margin-bottom:2rem; }
header.site h1 { font-size:1.5rem; margin:0; letter-spacing:.01em; }
header.site p { margin:.4rem 0 0; color:var(--muted); font-size:.95rem; }
a { color:#1a4d7a; }
h2 { font-size:1.2rem; margin-top:2.5rem; }
h3 { font-size:1rem; text-transform:uppercase; letter-spacing:.07em; color:var(--muted);
  margin:2rem 0 .5rem; font-family:system-ui, sans-serif; }
blockquote { margin:.5rem 0 .5rem 0; padding:.6rem 0 .6rem 1rem;
  border-left:3px solid var(--rule); color:#333; }
.cite { font:13px/1.5 system-ui, sans-serif; color:var(--muted); }
